    /// <summary>
    /// N1/N2: architectural CPU lockstep (A/X/Y/S/PC) for multiple budgets.
    /// P is intentionally not asserted here (see <see cref="NativeXvic_Managed_PCarry_DocumentedLag"/>).
    /// </summary>
    [Theory]
    [MemberData(nameof(CycleCounts))]
    public void NativeXvic_Managed_CpuRegs_Lockstep(string modelSelector, int cycles)
    {
        if (!ViceNativeXvic.IsAvailable)
            return;

        using var native = ViceNative.CreateInstance(modelSelector);
        native.Reset();
        var managed = MachineTestFactory.CreateVic20Machine(modelSelector);
        managed.Reset();

        for (var i = 0; i < cycles; i++)
        {
            native.Step();
            managed.Clock.Step();
        }

        var n = native.GetState();
        var m = managed.GetState();
        Assert.True(
            n.PC == m.PC && n.A == m.A && n.X == m.X && n.Y == m.Y && n.S == m.S,
            $"CPU mismatch after {cycles} cycles model={modelSelector}: native PC=${n.PC:X4} A=${n.A:X2} X=${n.X:X2} Y=${n.Y:X2} S=${n.S:X2} P=${n.P:X2}; managed PC=${m.PC:X4} A=${m.A:X2} X=${m.X:X2} Y=${m.Y:X2} S=${m.S:X2} P=${m.P:X2}");
    }

    /// <summary>
    /// Documents the known P.C lag: first diverge at cycle 25 on CMP $A003,X
    /// (kernal $FD44 DD 03 A0). Managed stages Carry; native EXPORT has it set.
    /// </summary>
    [Fact]
    public void NativeXvic_Managed_PCarry_DocumentedLag()
    {
        if (!ViceNativeXvic.IsAvailable)
            return;

        using var native = ViceNative.CreateInstance("vic20");
        native.Reset();
        var managed = MachineTestFactory.CreateVic20Machine("vic20");
        managed.Reset();

        var firstP = -1;
        for (var i = 0; i < 64; i++)
        {
            native.Step();
            managed.Clock.Step();
            var n = native.GetState();
            var m = managed.GetState();
            if (n.P != m.P)
            {
                firstP = i + 1;
                // Carry bit only at first lag.
                Assert.Equal(n.P & 0xFE, m.P & 0xFE);
                Assert.Equal(0x01, n.P & 0x01);
                Assert.Equal(0x00, m.P & 0x01);
                break;
            }
        }

        Assert.Equal(25, firstP);
    }

