/*
 * Side-effect-free bus peek for lockstep I/O samples (VIA1 $9110, VIA2 $9120,
 * VIC-I $9000). Routes $9000-page peeks through device peeks so timers/IFR
 * are not cleared the way a CPU mem_read would. Other addresses use
 * mem_bank_peek (monitor path).
 */
VICE_SHIM_API uint8_t vice_machine_peek_bus(void *machine, uint16_t address)
{
    uint8_t value = 0xff;

    vice_shim_ensure_sync_primitives();

    EnterCriticalSection(&g_state_lock);
    if (vice_shim_is_active_machine(machine)) {
        if ((address & 0xff00) == 0x9000) {
            /* $9000 VIC-I, $9110 VIA1, $9120 VIA2 (and mirrors on the page). */
            value = 0xff;
            if ((address & 0x0f) < 0x10 && (address & 0xf0) == 0x00) {
                value &= vic_peek((uint16_t)(address & 0x0f));
            }
            if (address & 0x10) {
                value &= via1_peek(address);
            }
            if (address & 0x20) {
                value &= via2_peek(address);
            }
            /* Pure VIC window $9000-$900F has neither VIA bit set. */
            if ((address & 0x30) == 0) {
                value = vic_peek((uint16_t)(address & 0x0f));
            }
        } else {
            value = mem_bank_peek(0, address, NULL);
        }
    }
    LeaveCriticalSection(&g_state_lock);

    return value;
}"}

